mapper.select:
SELECT price
FROM strategy_quotes
WHERE symbol = #{symbol} AND quoted_at <= #{upTo}
ORDER BY quoted_at DESC
LIMIT #{limit}

SELECT quoted_at, event_id, price
FROM strategy_quotes
WHERE symbol = #{symbol}
ORDER BY quoted_at DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM strategy_quotes
WHERE symbol = #{symbol}
  AND quoted_at < (
    SELECT quoted_at FROM strategy_quotes
    WHERE symbol = #{symbol}
    ORDER BY quoted_at DESC
    OFFSET (#{keep} - 1) LIMIT 1
  )
